      ACCEPT_TOKEN(anon_sym_attach);
      END_STATE();
    case 144:
      ACCEPT_TOKEN(sym_tag_missing_whitespace_trailing);
      if (lookahead != 0 &&
          lookahead != '}') ADVANCE(144);
